本局 {{user}} 就是下列档案中的角色，姓名与性别采用该档案。
<%
const project = function projectPromptState(state, query = '') {
    const entries = (value) => Object.entries(value || {});
    const take = (value, count) => Object.fromEntries(entries(value).slice(-count));
    const text = (value, limit = 500) => String(value || '').slice(0, limit);
    const place = state._时空?.当前地点;
    const playerId = state._开局?.主角ID || 'player';
    const player = state._实体?.[playerId];
    const matching = (id, name) => query.includes(id) || (name?.length > 1 && query.includes(name));
    const onsite = entries(state._实体).filter(([id, e]) => id !== playerId && e.类别 !== '危险源' && e.生命阶段 === '存活' && e.位面ID === place?.位面ID && e.地点ID === place?.地点ID).slice(-7);
    const owned = entries(state._能力).filter(([id]) => player?.能力ID[id]);
    const picked = new Set([
        ...owned.filter(([id, a]) => matching(id, a.名称)).slice(-6).map(([id]) => id),
        ...(state._查阅?.能力 || []),
        ...owned.filter(([, a]) => a.品阶 === '本源').map(([id]) => id),
        ...owned.slice(-4).map(([id]) => id),
    ].slice(0, 14));
    const abilities = Object.fromEntries(entries(state._能力).filter(([id]) => picked.has(id) || onsite.some(([, e]) => e.能力ID[id])).slice(0, 20).map(([id, a]) => [id, {
            名称: a.名称, 品阶: a.品阶, 等级: a.等级, 熟练度: a.熟练度, 进化次数: a.进化次数, 进化方向: a.进化方向,
            来源: { ...a.来源, 说明: text(a.来源?.说明, 300) }, 最近成长: take(a.成长记录, 2),
            用法: a.用法, 规则状态: a.规则状态, 描述: text(a.描述), 触发条件: text(a.触发条件, 200), 效果: a.效果,
            消耗: a.消耗, 冷却本地秒: a.冷却本地秒, 限制: text(a.限制, 300),
        }]));
    const entities = Object.fromEntries([[playerId, player], ...onsite].filter(([, e]) => !!e).map(([id, e]) => [id, {
            名称: e.名称, 类别: e.类别, 档案: id === playerId ? undefined : e.档案,
            位面ID: e.位面ID, 地点ID: e.地点ID, 生命阶段: e.生命阶段, 生命: e.生命, 战斗: e.战斗,
            资源: Object.fromEntries(entries(e.资源).filter(([key]) => key === 'energy' || picked.has(key) || (id !== playerId && abilities[key])).slice(0, 16)),
            能力ID: Object.fromEntries(entries(e.能力ID).filter(([key]) => abilities[key])),
            状态: take(e.状态, 8), 装备: take(e.装备, 12),
        }]));
    const allKnowledge = { ...state._见闻档案, ...state.叙事?.见闻 };
    const knowledge = entries(allKnowledge).filter(([, info]) => info.知情者ID?.[playerId]);
    const noteIds = new Set([
        ...(state._查阅?.见闻 || []),
        ...knowledge.filter(([id, info]) => matching(id, info.标题)).slice(-4).map(([id]) => id),
        ...entries(state.叙事?.见闻).filter(([, info]) => info.知情者ID?.[playerId] && (info.对象ID === place?.位面ID || info.对象ID === place?.地点ID || entities[info.对象ID])).slice(-4).map(([id]) => id),
        ...entries(state.叙事?.见闻).slice(-4).map(([id]) => id),
    ].slice(0, 10));
    const notes = Object.fromEntries(knowledge.filter(([id]) => noteIds.has(id)).map(([id, info]) => [id, { ...info, 内容: text(info.内容, 800) }]));
    const plane = state._时空?.位面目录?.[place?.位面ID];
    const narrative = state.叙事 || {};
    return {
        ...(state._更新错误 ? { 上轮结算反馈: text(state._更新错误), 待修复操作: state._待修复?.输入?.叙事?.本轮结算 } : {}),
        _开局: { 主角ID: playerId, 起源涅槃已获得: state._开局?.起源涅槃已获得, 伴生灵ID: state._开局?.伴生灵ID,
            档案: Object.fromEntries(entries(state._开局?.档案).filter(([, value]) => value).map(([key, value]) => [key, text(value, 500)])) },
        _时空: { 起源时刻秒: state._时空?.起源时刻秒, 当前地点: place,
            位面目录: plane ? { [place.位面ID]: { 名称: plane.名称, 简介: text(plane.简介, 600), 时钟: plane.时钟 } } : {} },
        _实体: entities, _能力: abilities,
        _任务: take(Object.fromEntries(entries(state._任务).filter(([id, t]) => ['进行中', '待结算'].includes(t.状态) || matching(id, t.名称))), 8),
        能力索引: owned.filter(([id]) => !picked.has(id)).slice(-24).map(([ID, a]) => ({ ID, 名称: a.名称, 品阶: a.品阶, 等级: a.等级 })),
        档案概况: { 能力总数: owned.length, 见闻总数: knowledge.length, 检索: '行动中提及能力名、见闻标题或ID可调入详情。完整内容留在档案。' },
        _物品: take(Object.fromEntries(entries(state._物品).filter(([, item]) => item.所在?.ID === playerId || item.所在?.ID === place?.地点ID)), 16),
        _结算: { ...state._结算, 冷却结束: Object.fromEntries(entries(state._结算?.冷却结束).filter(([id, end]) => end > (state._时空?.起源时刻秒 || 0) && id.startsWith(playerId + ':')).slice(0, 16)) },
        _复苏: state._复苏, _死亡记录: take(state._死亡记录, 1),
        最近结果: entries(state._运行账本?.events).slice(-4).map(([id, event]) => ({ ID: id, 结果: text(event.result, 600) })),
        叙事: { 首次资料完成: narrative.首次资料完成, 天气: text(narrative.天气, 120), 场景描述: text(narrative.场景描述, 600), 记忆摘要: narrative.记忆摘要, 见闻: notes,
            人物档案: Object.fromEntries(entries(narrative.人物档案).filter(([id, p]) => matching(id, p.名称) || p.别名?.some((name) => matching(id, name)) || (p.在场 && p.位面ID === place?.位面ID)).slice(-6)),
            关系: take(Object.fromEntries(entries(narrative.关系).filter(([, r]) => entities[r.对象ID] || entities[r.主体ID])), 8),
            外界事件: take(Object.fromEntries(entries(narrative.外界事件).filter(([, e]) => e.位面ID === place?.位面ID)), 6) },
        待审提案: take(state.待审提案, 4),
    };
};
const render = function formatPromptView(view) {
    const entries = (o) => Object.entries(o || {});
    const clean = (v) => {
        if (Array.isArray(v))
            return v.map(clean).filter(x => x !== undefined);
        if (v && typeof v === 'object')
            return Object.fromEntries(entries(v).map(([k, x]) => [k, clean(x)]).filter(([, x]) => x !== undefined));
        return v === null || v === undefined || v === '' ? undefined : v;
    };
    const lines = (value, indent = 0) => {
        const prefix = ' '.repeat(indent);
        if (Array.isArray(value))
            return value.map(x => prefix + '- ' + (typeof x === 'object' ? '\n' + lines(x, indent + 2) : String(x))).join('\n');
        return entries(value).map(([key, v]) => {
            if (v === undefined || (v && typeof v === 'object' && !Object.keys(v).length))
                return '';
            if (typeof v === 'object')
                return prefix + key + ':\n' + lines(v, indent + 2);
            return prefix + key + ': ' + String(v).replace(/\n/g, '\n' + prefix + '  ');
        }).filter(Boolean).join('\n');
    };
    const ability = Object.fromEntries(entries(view._能力).map(([id, a]) => {
        const effect = Object.values(a.效果 || {}).map((e) => {
            const p = e.参数 || {};
            if (e.规则ID === 'combat-strike-1')
                return '攻击：' + p.机制ID + '；倍率' + p.倍率 + '，固定伤害' + p.固定伤害 + '，耗时' + p.耗时本地秒 + '秒';
            if (e.规则ID === 'trial-convert')
                return '转化：' + p.mechanism + '，单次上限' + p.capacity;
            if (e.规则ID === 'trial-release')
                return '储能释放：倍率' + p.multiplier;
            if (e.规则ID === 'world-crossing')
                return '跨位面旅行；冷却采用虚海秒';
            if (e.规则ID === 'general-utility')
                return '技艺运用；专项检定加值' + (p.检定加值 || 0);
            return lines(p);
        }).filter(Boolean).join('；');
        return [id, { 名称: a.名称, 品阶: a.品阶, 掌握: 'Lv.' + a.等级 + '，熟练' + a.熟练度 + '/' + a.等级 * 5, 进化: a.进化方向, 来源: a.来源?.类型, 来历: a.来源?.说明, 用法: a.用法, 描述: a.描述, 触发: a.触发条件, 作用: effect, 消耗: a.消耗, 冷却: a.冷却本地秒 ? (a.冷却本地秒 + (a.效果?.travel ? '虚海秒' : '当地秒')) : undefined, 条件: a.限制 }];
    }));
    const actors = Object.fromEntries(entries(view._实体).map(([id, a]) => [id, { 名称: a.名称, 档案: a.档案, 状态: a.生命阶段, 生命: a.生命 ? a.生命.当前 + '/' + a.生命.上限 : undefined, 战斗: a.战斗, 资源: Object.fromEntries(entries(a.资源).map(([key, r]) => [key, r.名称 + ' ' + r.当前 + '/' + (r.上限 ?? '∞') + ' ' + r.单位])), 状态效果: a.状态, 装备: a.装备 }]));
    const cooldown = entries(view._结算?.冷却结束).map(([id, end]) => id + ' 剩余' + Math.max(0, end - view._时空.起源时刻秒) + '虚海秒');
    const plane = entries(view._时空?.位面目录)[0];
    const clock = plane?.[1]?.时钟;
    const local = clock ? clock.本地基准秒 + (view._时空.起源时刻秒 - clock.起源基准秒) * clock.本地每起源秒 : 0;
    const calendar = clock?.历法, minutes = calendar?.每小时分钟 || 60, seconds = calendar?.每分钟秒 || 60, hours = calendar?.每天小时 || 24;
    const dayIndex = Math.floor(local / (hours * minutes * seconds));
    let date = '历时 ' + Math.floor(local) + ' 秒';
    if (calendar?.每月天数?.length) {
        const yearDays = calendar.每月天数.reduce((sum, n) => sum + n, 0);
        let day = dayIndex % yearDays, month = 0;
        while (day >= calendar.每月天数[month])
            day -= calendar.每月天数[month++];
        date = calendar.名称 + ' ' + (calendar.元年 + Math.floor(dayIndex / yearDays)) + '年' + (month + 1) + '月' + (day + 1) + '日';
    }
    const time = String(Math.floor(local / (minutes * seconds)) % hours).padStart(2, '0') + ':' + String(Math.floor(local / seconds) % minutes).padStart(2, '0') + ':' + String(Math.floor(local) % seconds).padStart(2, '0');
    const snapshot = clean({
        当前世界: plane ? { 名称: plane[1].名称, 位面ID: plane[0], 地点: view._时空.当前地点, 当地时间: date + (calendar ? ' ' + time : ''), 流速: clock?.本地每起源秒, 背景: plane[1].简介 } : undefined,
        主角: { ID: view._开局?.主角ID, ...view._开局?.档案, 伴生灵ID: view._开局?.伴生灵ID },
        人物与数值: actors,
        能力: ability, 其余能力索引: view.能力索引,
        物品: view._物品, 任务: view._任务,
        最近死亡: Object.fromEntries(entries(view._死亡记录).map(([id, d]) => [id, { 实体ID: d.实体ID, 位面ID: d.位面ID, 地点ID: d.地点ID, 死因: Object.values(d.因果链 || {}).map((c) => ({ 机制: c.机制ID, 作用: c.作用条件, 伤害: c.实际伤害, 致死: c.直接致死 })), 衍生能力: Object.keys(d.授予能力ID || {}) }])),
        复苏: view._复苏 ? { 状态: view._复苏.阶段, 剩余虚海秒: view._复苏.完成起源秒 == null ? '尚未确定' : Math.max(0, view._复苏.完成起源秒 - view._时空.起源时刻秒) } : undefined,
        冷却: cooldown.length ? cooldown : undefined,
        档案概况: view.档案概况,
        最近结果: view.最近结果?.map((e) => e.结果),
    });
    const editable = clean({ ...view.叙事, 待审提案: view.待审提案 });
    return '<当前状态>\n' + lines(snapshot) + '\n结算版本: ' + view._结算?.状态版本 + '\n</当前状态>\n<叙事记录>\n' + lines(editable) + '\n</叙事记录>' +
        (view.上轮结算反馈 ? '\n<待处理更新>\n' + view.上轮结算反馈 + '\n' + lines(clean(view.待修复操作)) + '\n</待处理更新>' : '');
};
const recent = typeof getChatMessages === 'function' ? [-2,-1].flatMap(depth => getChatMessages(depth) || []).map(item => String(typeof item === 'string' ? item : item?.message ?? item?.mes ?? '').replace(/<UpdateVariable>[\s\S]*?<\/UpdateVariable>/gi, '')).join('\n') : '';
print(render(project(getvar('stat_data', { defaults: {} }) || {}, recent)));
%>

